package pe.com.asistencia.request.api;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import pe.com.asistencia.employee.repository.EmployeeRepository; import pe.com.asistencia.request.domain.*; import pe.com.asistencia.request.repository.EmployeeRequestRepository; import pe.com.asistencia.security.repository.UserRepository; import java.time.*; import java.util.*;
 import org.springframework.transaction.annotation.Transactional; import pe.com.asistencia.attendance.domain.PunchType; import pe.com.asistencia.attendance.repository.AttendanceDayRepository; import pe.com.asistencia.request.service.RequestEffectService; import pe.com.asistencia.security.service.SupervisorScopeService;
@RestController @RequestMapping("/api/v1/requests")
public class EmployeeRequestController {
 private final EmployeeRequestRepository requests; private final EmployeeRepository employees; private final UserRepository users; private final AttendanceDayRepository days; private final RequestEffectService effects; private final SupervisorScopeService scopes;
 public EmployeeRequestController(EmployeeRequestRepository r,EmployeeRepository e,UserRepository u,AttendanceDayRepository days,RequestEffectService effects,SupervisorScopeService scopes){requests=r;employees=e;users=u;this.days=days;this.effects=effects;this.scopes=scopes;}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public View submit(Authentication auth,@Valid @RequestBody SubmitRequest r){var employee=employees.findByUserUsernameIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Usuario sin empleado"));if(r.requestedFrom()!=null&&r.requestedTo()!=null&&r.requestedTo().isBefore(r.requestedFrom()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Rango inválido");if(r.type()==RequestType.CORRECTION&&(r.proposedPunchType()==null||r.proposedAt()==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"La corrección requiere tipo y hora propuesta");if(r.type()==RequestType.PERMISSION&&(r.requestedFrom()==null||r.requestedTo()==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"El permiso requiere inicio y fin");var day=r.affectedDate()==null?null:days.findByEmployeeIdAndWorkDate(employee.getId(),r.affectedDate()).orElse(null);return View.of(requests.save(new EmployeeRequest(employee,day,r.type(),r.affectedDate(),r.reason(),r.requestedFrom(),r.requestedTo(),r.proposedPunchType(),r.proposedAt(),r.requestedChange(),r.evidenceReference())));}
 @Transactional(readOnly=true) @GetMapping("/me") public List<View> mine(Authentication auth){var e=employees.findByUserUsernameIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Usuario sin empleado"));return requests.findByEmployeeIdOrderBySubmittedAtDesc(e.getId()).stream().map(View::of).toList();}
 @Transactional(readOnly=true) @GetMapping @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')") public List<View> pending(Authentication auth,@RequestParam(defaultValue="SUBMITTED") RequestStatus status){return requests.findByStatusOrderBySubmittedAtAsc(status).stream().filter(r->scopes.canAccess(auth,r.getEmployee().getId(),scopeDate(r))).map(View::of).toList();}
 @Transactional @PatchMapping("/{id}/review") @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')") public View review(Authentication auth,@PathVariable Long id,@Valid @RequestBody ReviewRequest r){var request=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Solicitud no encontrada"));if(!scopes.canAccess(auth,request.getEmployee().getId(),scopeDate(request)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"OUTSIDE_SUPERVISOR_SCOPE");var reviewer=users.findByUsernameIgnoreCase(auth.getName()).orElseThrow();try{request.review(reviewer,r.decision(),r.comment());if(r.decision()==RequestStatus.APPROVED)effects.applyApproved(request,reviewer);}catch(IllegalStateException|IllegalArgumentException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,ex.getMessage());}return View.of(requests.save(request));}
 private LocalDate scopeDate(EmployeeRequest request){return request.getAffectedDate()==null?LocalDate.now():request.getAffectedDate();}
 public record SubmitRequest(@NotNull RequestType type,@NotNull LocalDate affectedDate,@NotBlank @Size(max=1000) String reason,Instant requestedFrom,Instant requestedTo,PunchType proposedPunchType,Instant proposedAt,@Size(max=1000) String requestedChange,@Size(max=500) String evidenceReference){} public record ReviewRequest(@NotNull RequestStatus decision,@Size(max=1000) String comment){} public record View(Long id,Long employeeId,String employeeCode,String employeeName,String employeePhotoUrl,RequestType type,LocalDate affectedDate,String reason,Instant requestedFrom,Instant requestedTo,PunchType proposedPunchType,Instant proposedAt,String requestedChange,String evidenceReference,RequestStatus status,String reviewedBy,String reviewComment,Instant submittedAt,Instant resolvedAt){static View of(EmployeeRequest r){var e=r.getEmployee();return new View(r.getId(),e.getId(),e.getCode(),e.getFirstNames()+" "+e.getLastNames(),e.getPhotoUrl(),r.getType(),r.getAffectedDate(),r.getReason(),r.getRequestedFrom(),r.getRequestedTo(),r.getProposedPunchType(),r.getProposedAt(),r.getRequestedChange(),r.getEvidenceReference(),r.getStatus(),r.getReviewedBy()==null?null:r.getReviewedBy().getUsername(),r.getReviewComment(),r.getSubmittedAt(),r.getResolvedAt());}}
}
